// Gate wrapper to lazy-load AuditTrailPanel on visibility
import React, { useEffect, useRef, useState } from 'react';

export function AuditGate({ onLoad }) {
  const ref = useRef(null);
  const [loaded, setLoaded] = useState(false);
  useEffect(() => {
    if (!ref.current) return;
    const obs = new IntersectionObserver((entries) => {
      if (entries[0].isIntersecting) {
        import('./AuditTrailPanel').then((mod) => {
          onLoad && onLoad(mod.default);
          setLoaded(true);
        });
        obs.disconnect();
      }
    });
    obs.observe(ref.current);
    return () => obs.disconnect();
  }, [onLoad]);
  return <div ref={ref} aria-label="AuditGate" style={{ minHeight: 20 }} />;
}
